#!/usr/bin/env python3
"""Adapt a repository created from the Big-3 template.

Run from the repository root. With no step flag, runs everything in one pass:
the local steps, the GitHub steps (when gh can reach the repository) and the
final check. A step whose work is already done says so and is skipped, so
re-running is safe.

Local steps:
  --clean       delete the template's generated files (Scorecard results,
                badge JSON, committed SAST reports, CHANGELOG.md)
  --rename      replace the template's owner/repo and OWNER/REPO placeholders
                with the repository behind `git remote get-url origin`
  --version     write the current version to .release-please-manifest.json
  --contact     fill the Code of Conduct enforcement contact
  --sonar       fill the SonarQube Cloud organisation and project keys
  --signing     propose `git config --local` commands for SSH commit signing

GitHub steps (need `gh auth login` as a repo admin):
  --gh-vars     ask for each unset Actions secret and variable, propose `gh ... set`
  --governance  propose scripts/apply-governance.sh (ruleset + repo settings)
  --workflow    only reads: check everything above; exits 1 on a failure

How much it asks:
  (default)     every question, every file edit and every command is confirmed
  --trust       use every value it can detect, accept every command; only asks
                for what it cannot find (contact, secret values, ...)
  --yes         never asks; uses detected values and skips the rest; commands
                are printed unless --accept-cmd
  --accept-cmd  run proposed commands without asking
  --print-cmd   never run commands; print them for you to run yourself
  --dry-run     change no file and run no command; show what would happen

Commands that change something (git config, ssh-keygen, gh ... set,
apply-governance.sh) are always shown. Read-only queries (git remote,
gh ... list, gh api reads) run on their own. Standard library only; Python 3.9+.
"""

from __future__ import annotations

import argparse
import getpass
import json
import os
import re
import shlex
import shutil
import subprocess
import sys
from pathlib import Path

TEMPLATE_SLUG = "Julian52575/Big-3-Governed-Template"
PLACEHOLDER_SLUG = "OWNER/REPO"
PACKAGE_PLACEHOLDER = '"package-name": "REPO"'
CONTACT_PLACEHOLDER = "[INSERT CONTACT METHOD]"
SONAR_FILE = Path(".sast/sonar-project.properties")
SONAR_PLACEHOLDERS = {
    "sonar.organization": "REPLACE_WITH_ORGANIZATION_KEY",
    "sonar.projectKey": "REPLACE_WITH_PROJECT_KEY",
}
MANIFEST = Path(".release-please-manifest.json")
TEMPLATE_MARKERS = [TEMPLATE_SLUG, TEMPLATE_SLUG.replace("/", "%2F"), PLACEHOLDER_SLUG, PACKAGE_PLACEHOLDER]

# Generated by workflows; a new repository must not show the template's results.
TEMPLATE_FILES = [
    "CHANGELOG.md",
    ".sast/openssf/SCORECARD.md",
    ".readme-badges/scorecard-results.json",
    ".readme-badges/scorecard-badge.json",
]
SAST_REPORT_DIR = Path(".sast/report")

# (name, kind, required, help). `kind` is "secret" or "variable".
GH_SETTINGS = [
    ("RELEASE_PLEASE_GITHUB_TOKEN", "secret", True,
     "Fine-grained PAT or GitHub App token on this repo with Contents and Pull "
     "requests read/write. release-please.yml fails without it."),
    ("SONARQUBE_TOKEN", "secret", False,
     "SonarQube Cloud analysis token (My Account -> Security). Turns on the "
     "SonarQube job in ci-sast.yml."),
    ("SAST_REPORT_TOKEN", "secret", False,
     "Fine-grained PAT with Contents read/write. Lets ci-sast.yml commit "
     "reports to main; needs a ruleset bypass if main is protected."),
    ("DISCORD_WEBHOOK_URL", "secret", False,
     "Discord channel webhook URL (Channel settings -> Integrations -> "
     "Webhooks). Turns on notify-discord-review-requested.yml."),
    ("MAKE_PR_DRAFT", "variable", False,
     "Set to `true` to have make-pr-draft.yml turn new PRs into drafts."),
]

SEMVER = re.compile(r"^\d+\.\d+\.\d+(-[0-9A-Za-z.-]+)?$")


class Ui:
    """Questions, confirmations and command proposals, by mode.

    ask_mode: "ask" (default), "trust" (--trust) or "never" (--yes).
    cmd_mode: "ask" (default), "accept" (--accept-cmd, --trust) or "print" (--print-cmd).
    """

    def __init__(self, ask_mode: str, cmd_mode: str, dry_run: bool):
        self.ask_mode = ask_mode
        self.cmd_mode = cmd_mode
        self.dry_run = dry_run
        self.printed: list[str] = []  # --print-cmd: repeated at the end, ready to copy

    def ask(self, prompt: str, default: str = "", secret: bool = False) -> str:
        """`default` is a value the script found or suggests; --trust and --yes take it."""
        if self.ask_mode == "never" or (self.ask_mode == "trust" and default):
            if default:
                print(f"  {prompt}: {default}")
            return default
        suffix = f" [{default}]" if default else ""
        if secret:
            # getpass keeps the value off the screen
            return getpass.getpass(f"  {prompt}{suffix}: ").strip() or default
        return input(f"  {prompt}{suffix}: ").strip() or default

    def confirm(self, prompt: str) -> bool:
        if self.ask_mode != "ask":
            return True
        return not input(f"  {prompt} [Y/n] ").strip().lower().startswith("n")

    def command(self, cmd: list[str], *, stdin: str | None = None, shown: str | None = None,
                interactive: bool = False) -> bool:
        """Propose `cmd`; run it only once accepted. True if it ran and succeeded.

        `shown` replaces the displayed command line, e.g. to keep a secret out of it.
        """
        line = shown or shlex.join(cmd)
        print(f"  $ {line}")
        if self.cmd_mode == "print":
            self.printed.append(line)
        if not self._accepted("run it?"):
            return False
        return self._run(cmd, stdin, interactive)

    def commands(self, cmds: list[list[str]]) -> bool:
        """Propose several commands as one step: all of them run, or none."""
        for cmd in cmds:
            print(f"  $ {shlex.join(cmd)}")
            if self.cmd_mode == "print":
                self.printed.append(shlex.join(cmd))
        if not self._accepted(f"run these {len(cmds)} commands?"):
            return False
        return all(self._run(cmd, None, False) for cmd in cmds)

    def _accepted(self, question: str) -> bool:
        if self.dry_run or self.cmd_mode == "print":
            return False
        if self.cmd_mode == "ask" and not input(f"    {question} [y/N] ").strip().lower().startswith("y"):
            print("    not run")
            return False
        return True

    def _run(self, cmd: list[str], stdin: str | None, interactive: bool) -> bool:
        if interactive:
            return subprocess.run(cmd, check=False).returncode == 0
        r = subprocess.run(cmd, check=False, text=True, capture_output=True, input=stdin)
        out = (r.stdout if r.returncode == 0 else r.stderr).strip()
        if out:
            print("    " + out.replace("\n", "\n    "))
        return r.returncode == 0


def heading(text: str) -> None:
    print(f"\n== {text}")


def done(text: str) -> None:
    print(f"  already done: {text}")


def run(cmd: list[str], check: bool = True) -> subprocess.CompletedProcess:
    return subprocess.run(cmd, check=check, text=True, capture_output=True)


def git(*args: str) -> str:
    return run(["git", *args]).stdout.strip()


def git_config(key: str) -> str:
    return run(["git", "config", "--get", key], check=False).stdout.strip()


def origin_slug() -> str | None:
    """owner/repo from the origin URL (SSH or HTTPS)."""
    r = run(["git", "remote", "get-url", "origin"], check=False)
    m = re.search(r"github\.com[:/]([^/]+)/(.+?)(?:\.git)?/?$", r.stdout.strip())
    if not m:
        return None
    slug = f"{m.group(1)}/{m.group(2)}"
    # A renamed repository keeps redirecting from its old URL; ask GitHub for the current name.
    if shutil.which("gh"):
        r = run(["gh", "repo", "view", slug, "--json", "nameWithOwner", "--jq", ".nameWithOwner"], check=False)
        if r.returncode == 0 and r.stdout.strip():
            return r.stdout.strip()
    return slug


def gh_problem(slug: str | None) -> str | None:
    """Why the GitHub steps cannot run, or None when they can."""
    if not shutil.which("gh"):
        return "gh (GitHub CLI) is not installed: https://cli.github.com/"
    if run(["gh", "auth", "status"], check=False).returncode != 0:
        return "gh is not authenticated: run `gh auth login`."
    if not slug:
        return "the origin remote is not a GitHub repository."
    if run(["gh", "api", f"repos/{slug}", "--silent"], check=False).returncode != 0:
        return f"github.com/{slug} is not reachable with this gh login (check `gh auth status`)."
    return None


def tracked_text_files() -> list[Path]:
    files = []
    for name in git("ls-files").splitlines():
        path = Path(name)
        # README-ADAPT.md documents the placeholders themselves
        if path.name in ("adapt.py", "README-ADAPT.md", "package-lock.json") or not path.is_file():
            continue
        if name in TEMPLATE_FILES:  # generated results: --clean deletes them
            continue
        try:
            path.read_text(encoding="utf-8")
        except (UnicodeDecodeError, OSError):
            continue
        files.append(path)
    return files


def files_containing(needles: list[str]) -> list[Path]:
    return [p for p in tracked_text_files() if any(n in p.read_text(encoding="utf-8") for n in needles)]


def replace_in_files(ui: Ui, replacements: dict[str, str]) -> None:
    for path in tracked_text_files():
        text = path.read_text(encoding="utf-8")
        new = text
        for old, value in replacements.items():
            new = new.replace(old, value)
        if new != text:
            print(f"  {'would update' if ui.dry_run else 'updated'} {path}")
            if not ui.dry_run:
                path.write_text(new, encoding="utf-8")


def manifest_version() -> str:
    return json.loads(MANIFEST.read_text()).get(".", "") if MANIFEST.exists() else ""


def signing_configured() -> bool:
    return git_config("commit.gpgsign") == "true" and bool(git_config("user.signingkey"))


def sonar_defaults(slug: str | None) -> dict[str, str]:
    """SonarQube Cloud's own defaults when importing a GitHub repository."""
    if not slug:
        return {}
    owner, repo = slug.split("/")
    return {"sonar.organization": owner.lower(), "sonar.projectKey": f"{owner}_{repo}"}


# --- local steps --------------------------------------------------------------

def step_clean(ui: Ui) -> None:
    heading("Remove the template's generated files")
    targets = [Path(p) for p in TEMPLATE_FILES if Path(p).exists()]
    if SAST_REPORT_DIR.is_dir():
        targets += [p for p in SAST_REPORT_DIR.iterdir() if p.name != ".gitkeep"]
    if not targets:
        done("no template results left")
        return
    for p in targets:
        print(f"  {p}")
    if not ui.confirm("Delete these?"):
        return
    if ui.dry_run:
        print("  would remove them")
        return
    for p in targets:
        shutil.rmtree(p) if p.is_dir() else p.unlink()
    print("  removed; the workflows regenerate them for this repository")


def step_rename(ui: Ui) -> None:
    heading("Point owner/repo references at this repository")
    left = files_containing(TEMPLATE_MARKERS)
    if not left:
        done("no template owner/repo reference left")
        return
    detected = origin_slug()
    if detected == TEMPLATE_SLUG:
        print("  skipped: origin is the template itself")
        return
    print("  left in: " + ", ".join(map(str, left)))
    slug = ui.ask("owner/repo of this repository", detected or "")
    if not re.fullmatch(r"[\w.-]+/[\w.-]+", slug):
        print("  skipped: no valid owner/repo (set the origin remote, or type it)")
        return
    replace_in_files(ui, {
        TEMPLATE_SLUG: slug,
        TEMPLATE_SLUG.replace("/", "%2F"): slug.replace("/", "%2F"),
        PLACEHOLDER_SLUG: slug,
        PACKAGE_PLACEHOLDER: f'"package-name": "{slug.split("/")[1]}"',
    })


def step_version(ui: Ui) -> None:
    heading("Current version (.release-please-manifest.json)")
    current = manifest_version()
    if current and current != "0.0.0":
        done(f"version {current}")
        return
    # 0.0.0 is both the template's value and a valid start, so the default keeps it
    version = ui.ask("Current version of the project (release-please bumps from it)", current or "0.0.0")
    if not SEMVER.match(version):
        print(f"  skipped: '{version}' is not a semantic version like 1.4.0")
        return
    if version == current:
        print(f"  kept {version}")
        return
    print(f"  {'would set' if ui.dry_run else 'set'} version {version}")
    if not ui.dry_run:
        MANIFEST.write_text(f'{{ ".": "{version}" }}\n')


def step_contact(ui: Ui) -> None:
    heading("Code of Conduct enforcement contact")
    path = Path("CODE_OF_CONDUCT.md")
    if not path.exists() or CONTACT_PLACEHOLDER not in path.read_text():
        done("contact set")
        return
    contact = ui.ask("Where to report conduct issues, e.g. an email address (blank skips)")
    if contact:
        replace_in_files(ui, {CONTACT_PLACEHOLDER: contact})


def step_sonar(ui: Ui) -> None:
    heading("SonarQube Cloud keys (.sast/sonar-project.properties)")
    text = SONAR_FILE.read_text()
    missing = [k for k, v in SONAR_PLACEHOLDERS.items() if f"{k}={v}" in text]
    if not missing:
        done("keys set")
        return
    print("  Used once the SONARQUBE_TOKEN secret is set; see .sast/README.md.")
    defaults = sonar_defaults(origin_slug())
    for key in missing:
        value = ui.ask(f"{key} (blank skips)", defaults.get(key, ""))
        if value:
            text = text.replace(f"{key}={SONAR_PLACEHOLDERS[key]}", f"{key}={value}")
    if text != SONAR_FILE.read_text():
        print(f"  {'would update' if ui.dry_run else 'updated'} {SONAR_FILE}")
        if not ui.dry_run:
            SONAR_FILE.write_text(text)


def default_signing_key() -> str:
    """The key the user most likely signs with: their configured one, else id_ed25519."""
    configured = git_config("user.signingkey")
    if configured and Path(configured).expanduser().exists():
        return configured
    preferred = Path.home() / ".ssh" / "id_ed25519.pub"
    if preferred.exists():
        return str(preferred)
    keys = sorted(Path.home().glob(".ssh/*.pub"))
    return str(keys[0]) if keys else ""


def step_signing(ui: Ui) -> None:
    heading("Commit signing for this clone (git config --local)")
    if signing_configured():
        done(f"commits signed with {git_config('user.signingkey')}")
        return
    if ui.ask_mode == "never":
        print("  skipped with --yes: picking a key is personal; run --signing")
        return
    for k in sorted(Path.home().glob(".ssh/*.pub")):
        print(f"    {k}")
    choice = ui.ask("Public key to sign with (path), or `new` to generate one", default_signing_key() or "new")
    if choice == "new":
        key = Path.home() / ".ssh" / "id_ed25519_signing"
        email = git_config("user.email") or "signing"
        generated = ui.command(["ssh-keygen", "-t", "ed25519", "-C", email, "-f", str(key)], interactive=True)
        if not generated and ui.cmd_mode != "print" and not ui.dry_run:
            print("  skipped: no key generated")
            return
        pub = Path(f"{key}.pub")
    else:
        pub = Path(choice).expanduser()
        if not pub.exists():
            print(f"  skipped: {pub} not found")
            return
    ui.commands([["git", "config", "--local", key, value] for key, value in
                 {"gpg.format": "ssh", "user.signingkey": str(pub),
                  "commit.gpgsign": "true", "tag.gpgsign": "true"}.items()])
    print("  Commits also need a sign-off: use `git commit -s`.")
    print("  Register the key on GitHub as a *Signing Key* (Settings -> SSH and GPG keys), or with gh:")
    ui.command(["gh", "ssh-key", "add", str(pub), "--type", "signing", "--title", "commit signing"])


# --- GitHub steps -------------------------------------------------------------

def gh_names(slug: str, kind: str) -> set[str]:
    r = run(["gh", kind, "list", "-R", slug, "--json", "name", "--jq", ".[].name"], check=False)
    return set(r.stdout.split()) if r.returncode == 0 else set()


def step_gh_vars(ui: Ui, slug: str) -> None:
    heading(f"Actions secrets and variables for {slug}")
    existing = {"secret": gh_names(slug, "secret"), "variable": gh_names(slug, "variable")}
    for name, kind, required, help_text in GH_SETTINGS:
        if name in existing[kind]:
            done(f"{kind} {name} set")
            continue
        print(f"\n  {name} ({kind}, {'required' if required else 'optional'}, not set)")
        print(f"    {help_text}")
        if kind == "secret" and ui.cmd_mode == "print":
            # gh prompts for the value itself, so it never lands in the printout
            ui.command(["gh", "secret", "set", name, "-R", slug])
            continue
        value = ui.ask(f"value for {name} (blank skips)", secret=kind == "secret")
        if not value:
            continue
        if kind == "secret":
            cmd = ["gh", "secret", "set", name, "-R", slug]
            ui.command(cmd, stdin=value, shown=shlex.join(cmd) + "   # value sent on stdin")
        else:
            ui.command(["gh", "variable", "set", name, "-R", slug, "--body", value])


def governance_state(slug: str) -> dict[str, bool]:
    r = run(["gh", "api", f"repos/{slug}/rules/branches/main", "--jq",
             '.[] | select(.type=="required_status_checks") | .parameters.required_status_checks[].context'],
            check=False)
    perm = run(["gh", "api", f"repos/{slug}/actions/permissions/workflow", "--jq",
                ".default_workflow_permissions"], check=False)
    merges = run(["gh", "api", f"repos/{slug}", "--jq",
                  "[.allow_squash_merge, .allow_merge_commit, .allow_rebase_merge] | @tsv"], check=False)
    return {
        "main requires ci-required": "ci-required" in r.stdout.split(),
        "read-only default GITHUB_TOKEN": perm.returncode == 0 and perm.stdout.strip() == "read",
        "squash-only merges": merges.stdout.split() == ["true", "false", "false"],
    }


def step_governance(ui: Ui, slug: str) -> None:
    heading(f"Repository governance for {slug}")
    state = governance_state(slug)
    if all(state.values()):
        done(", ".join(state))
        return
    for what, ok in state.items():
        print(f"  {'ok ' if ok else 'missing'} {what}")
    print("  apply-governance.sh applies .github/rulesets/main.json and the merge, Actions and security settings.")
    ui.command(["bash", "scripts/apply-governance.sh", slug], interactive=True)


def step_workflow_check(slug: str | None) -> int:
    heading("Configuration check")
    problems = 0

    def report(ok: bool | None, text: str) -> None:
        nonlocal problems
        mark = {True: "ok  ", False: "FAIL", None: "warn"}[ok]
        problems += ok is False
        print(f"  [{mark}] {text}")

    report(bool(slug), f"origin remote: {slug or 'not a GitHub URL'}")
    left = [str(p) for p in files_containing(TEMPLATE_MARKERS)]
    if slug == TEMPLATE_SLUG:
        report(None, "origin is the template itself; owner/repo references not checked")
    else:
        report(not left, "owner/repo references " + (f"left in: {', '.join(left)} (run --rename)" if left else "updated"))
    generated = [p for p in TEMPLATE_FILES if Path(p).exists()]
    report(None if generated else True,
           f"template results present: {', '.join(generated)} (run --clean)" if generated else "no template results left")
    version = manifest_version()
    report(bool(SEMVER.match(version)), f".release-please-manifest.json version: {version or 'missing'}")
    contact_set = CONTACT_PLACEHOLDER not in Path("CODE_OF_CONDUCT.md").read_text()
    report(contact_set or None, "Code of Conduct contact " + ("set" if contact_set else "not set (run --contact)"))
    report(signing_configured(), "commit signing " + ("configured" if signing_configured() else "not configured (run --signing)"))
    hooks = git_config("core.hooksPath") == ".githooks"
    report(hooks or None, "git hooks " + ("enabled" if hooks else "not enabled (enter `nix develop`)"))

    problem = gh_problem(slug)
    if problem:
        report(False, f"GitHub checks skipped: {problem}")
        return problems
    secrets, variables = gh_names(slug, "secret"), gh_names(slug, "variable")
    for name, kind, required, _ in GH_SETTINGS:
        present = name in (secrets if kind == "secret" else variables)
        report(True if present else (False if required else None),
               f"{kind} {name} " + ("set" if present else "not set" + ("" if required else " (optional)")))
    if "SONARQUBE_TOKEN" in secrets:
        filled = not any(f"{k}={v}" in SONAR_FILE.read_text() for k, v in SONAR_PLACEHOLDERS.items())
        report(filled, "SonarQube keys " + ("set" if filled else "still placeholders (run --sonar)"))
    for what, ok in governance_state(slug).items():
        report(ok, what if ok else f"{what}: no (run --governance)")
    return problems


# --- entry point --------------------------------------------------------------

LOCAL_STEPS = [("clean", step_clean), ("rename", step_rename), ("version", step_version),
               ("contact", step_contact), ("sonar", step_sonar), ("signing", step_signing)]
GITHUB_STEPS = [("gh_vars", step_gh_vars), ("governance", step_governance)]


def main() -> int:
    parser = argparse.ArgumentParser(
        prog="adapt.py",
        description=__doc__.split("\n\n", 1)[0],
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""\
which one fits you:
  ./adapt.py                 guided: asks every question, you accept each command
  ./adapt.py --trust         uses what it detects, runs commands, asks only for
                             what it cannot find (contact, secret values)
  ./adapt.py --print-cmd     runs no command; prints the ones you choose to run
                             (add --dry-run to change no file either)
  ./adapt.py --accept-cmd    everything in one pass, no command confirmations

single steps:
  ./adapt.py --rename --yes  only rewrite owner/repo from origin, no questions
  ./adapt.py --gh-vars       set the missing Actions secrets and variables
  ./adapt.py --workflow      check the result; exit status 1 on a failure

Already-adapted fields are detected and skipped, so re-running is safe.
See README-ADAPT.md for what each step changes.""",
    )
    steps = parser.add_argument_group("local steps (default: every step, then GitHub, then --workflow)")
    steps.add_argument("--clean", action="store_true", help="delete the template's generated results")
    steps.add_argument("--rename", action="store_true", help="replace template owner/repo references with origin's")
    steps.add_argument("--version", action="store_true", help="set the current version in .release-please-manifest.json")
    steps.add_argument("--contact", action="store_true", help="set the Code of Conduct contact")
    steps.add_argument("--sonar", action="store_true", help="set the SonarQube Cloud organisation and project keys")
    steps.add_argument("--signing", action="store_true",
                       help="propose `git config --local` commands for SSH commit signing")
    github = parser.add_argument_group("GitHub steps (need gh authenticated as a repo admin)")
    github.add_argument("--gh-vars", action="store_true",
                        help="ask for each unset Actions secret and variable, propose `gh ... set`")
    github.add_argument("--governance", action="store_true", help="propose scripts/apply-governance.sh")
    github.add_argument("--workflow", action="store_true",
                        help="check the whole configuration (read-only); exit 1 on a failure")
    modes = parser.add_argument_group("how much it asks (default: every question and command)")
    answers = modes.add_mutually_exclusive_group()
    answers.add_argument("--trust", action="store_true",
                         help="use every detected value and accept every command; "
                              "ask only for what it cannot find")
    answers.add_argument("-y", "--yes", action="store_true",
                         help="never ask: use detected values, skip what is missing (signing, secrets); "
                              "commands are printed, or run with --accept-cmd")
    cmds = modes.add_mutually_exclusive_group()
    cmds.add_argument("--accept-cmd", action="store_true", help="run every proposed command without asking")
    cmds.add_argument("--print-cmd", action="store_true", help="never run commands; print them for you to run")
    modes.add_argument("-n", "--dry-run", action="store_true",
                       help="show what would change; change no file, run no command")
    args = parser.parse_args()
    if args.trust and args.print_cmd:
        parser.error("--trust accepts commands; it cannot be combined with --print-cmd")

    os.chdir(git("rev-parse", "--show-toplevel"))
    cmd_mode = "accept" if (args.accept_cmd or args.trust) else "print" if args.print_cmd else "ask"
    if args.yes and cmd_mode == "ask":
        cmd_mode = "print"  # nobody is there to answer
    ui = Ui("trust" if args.trust else "never" if args.yes else "ask", cmd_mode, args.dry_run)

    chosen_local = [fn for name, fn in LOCAL_STEPS if getattr(args, name)]
    chosen_github = [fn for name, fn in GITHUB_STEPS if getattr(args, name)]
    everything = not (chosen_local or chosen_github or args.workflow)
    if everything:
        chosen_local = [fn for _, fn in LOCAL_STEPS]
        chosen_github = [fn for _, fn in GITHUB_STEPS]

    try:
        for fn in chosen_local:
            fn(ui)
        slug = origin_slug()
        if chosen_github:
            problem = gh_problem(slug)
            if problem and not everything:
                print(f"\nerror: {problem}", file=sys.stderr)
                return 1
            if problem:
                heading("GitHub steps")
                print(f"  skipped: {problem}\n  Fix it, then run ./adapt.py again (finished steps are skipped).")
            else:
                for fn in chosen_github:
                    fn(ui, slug)
        if args.workflow or everything:
            failures = step_workflow_check(slug)
            if args.workflow:
                return 1 if failures else 0
    except (KeyboardInterrupt, EOFError):
        print("\naborted")
        return 130
    if ui.printed:
        print("\nNothing was run. The commands, in order, for you to pick from:\n")
        print("\n".join(ui.printed))
    if chosen_local and not args.dry_run:
        print("\nReview the file changes with `git diff`, then commit (git commit -s).")
    return 0


if __name__ == "__main__":
    sys.exit(main())
